// §42 pause/drain run-time options (test-only).  pause_mode == 0 keeps the
// ordinary natural run completely inert; only +pause-mode>0 drives the
// pause control block inserted into tick().
static uint32_t pause_mode   = 0;      // 0=off, 1=mode1, 2=mode2
static uint32_t pause_offers = 4;
static uint32_t pause_window = 10000;
// +pause-require-quiet=0|1 (default 1).  A quiet ("A admitted obligations
// finished") can only appear after the shared source really detaches, i.e.
// only when physical_bypass != 0.  A mode0 "closed" run never detaches and
// therefore can never report dbg_pause_a_quiet, so this gate allows a focused
// early-resumption window to run without the quiet obligation while every
// other closure test is kept.
static bool     pause_require_quiet = true;
// +memory-b-delay=N (default 0): bounded extra latency inserted BEFORE the
// ACTUAL shared DDR B channel first offers BVALID for a queued child.  Once
// offered, BVALID is held stable until its handshake.  This only inserts idle
// cycles; it never withdraws a held response.
static uint32_t memory_b_delay      = 0;
// +memory-backpressure=1 (default 0): periodic READY backpressure on the DDR
// AW/W/AR request channels only.  DDR RVALID/BVALID are testbench-driven
// responses and are never withdrawn; a held response stays stable.
static uint32_t memory_backpressure = 0;

