replacements.new:
void drive_ddr() {
    ddr_setup_wait = false;
    ddr_model_empty = mem_q.empty();
    // Optional +memory-backpressure=1: periodic READY backpressure on the
    // DDR AW/W/AR request channels ONLY.  The DDR responses (RVALID /
    // BVALID) are testbench-driven and are never withdrawn; a held
    // response stays stable until its own handshake.
    const bool bp_ready = (memory_backpressure == 0) || ((g_cycle & 3L) != 3L);
    top->ddr_aw_ready = bp_ready ? 1 : 0;
    top->ddr_w_ready  = bp_ready ? 1 : 0;
    if (write_tail_pause != 0 && !caw_q.empty()) {
        CawEnt& c = caw_q.front();
        if (((c.id >> 4) & 3u) == 2u && c.len == 255 && c.got == 248 && !c.tail_hold_seen) {
            c.tail_hold_seen = true;
            c.tail_release_cycle = g_cycle + write_tail_pause;
            ++write_tail_holds;
            trace_event("ddr_w_tail_hold", c.id, c.addr, write_tail_pause);
        }
        if (c.tail_hold_seen && g_cycle < c.tail_release_cycle) {
            top->ddr_w_ready = 0;
            ++write_tail_hold_cycles;
        }
    }
    top->ddr_ar_ready = (bp_ready && mem_q.size() < 16) ? 1 : 0;
    // BVALID is offered only after its +memory-b-delay release cycle; once
    // offered it stays asserted until the B handshake (held-stable rule).
    if (!cb_q.empty() && g_cycle >= cb_release_q.front()) {
        top->ddr_b_valid = 1;
        top->ddr_b_id    = (uint8_t)cb_q.front();
        top->ddr_b_resp  = 0;
    } else {
        top->ddr_b_valid = 0;
        top->ddr_b_id    = 0;
        top->ddr_b_resp  = 0;
    }

