// ---- (2) per-DMA physical read / write data geometry --------------
// The classifier works on PHYSICAL addresses.  In shared-source mode
// both DMAs read the same source PA, so their read beats land in the
// SAME class (NR_VSRC); the acceptance therefore requires the combined
// source read count (2*want) and an empty A-only class.  The two
// destinations stay physically disjoint and each must carry `want`
// beats (byte-wise content is checked in part (1) above).
const uint64_t want = (uint64_t)beats;
if (shared_source) {
    CHECK(nat_pr_beats[NR_VSRC] == 2ULL * want,
          "natural(shared): combined physical source read beats != "
          "2*natural_bytes/8");
    CHECK(nat_pr_beats[NR_ASRC] == 0,
          "natural(shared): A-only source class must be empty when the "
          "source PA is shared with V");
} else {
    CHECK(nat_pr_beats[NR_VSRC] == want,
          "natural: V physical source read beats != natural_bytes/8");
    CHECK(nat_pr_beats[NR_ASRC] == want,
          "natural: A physical source read beats != natural_bytes/8");
}

replacements.new:
// ---- (2) per-DMA physical read / write data geometry --------------
// The classifier works on PHYSICAL addresses.  In shared-source mode
// both DMAs read the same source PA, so their read beats land in the
// SAME class (NR_VSRC) and the A-only class must stay empty.  The
// physical shared-source read count depends ONLY on the real detach
// state reported by the RTL:
//   * not detached (mode0 "closed"): one merged child covers both
//     parents -> exactly `want` source read beats;
//   * detached (mode>0 once A's registered obligations quiesce): the
//     RTL has already returned dbg_shared_cut_bytes of A's logical
//     stream, so the physical source read count is 2*want-cut_bytes/8.
// In BOTH states the per-parent LOGICAL returns must reach the full
// natural_bytes for V and A.
const uint64_t want = (uint64_t)beats;
if (shared_source) {
    CHECK(nat_pr_beats[NR_ASRC] == 0,
          "natural(shared): A-only source class must be empty when the "
          "source PA is shared with V");
    const uint64_t src_cut_beats = (uint64_t)(top->dbg_shared_cut_bytes / 8);
    const uint64_t src_expect = top->dbg_shared_detached
                              ? (2ULL * want - src_cut_beats)
                              : want;
    CHECK(nat_pr_beats[NR_VSRC] == src_expect,
          "natural(shared): physical shared-source read beats != "
          "(detached ? 2*want - cut_bytes/8 : want)");
    CHECK((uint64_t)top->dbg_pause_v_rbytes == (uint64_t)natural_bytes &&
          (uint64_t)top->dbg_pause_a_rbytes == (uint64_t)natural_bytes,
          "natural(shared): logical returned V/A bytes must each equal "
          "natural_bytes");
} else {
    CHECK(nat_pr_beats[NR_VSRC] == want,
          "natural: V physical source read beats != natural_bytes/8");
    CHECK(nat_pr_beats[NR_ASRC] == want,
          "natural: A physical source read beats != natural_bytes/8");
}

// §50: the shared source raw AR is now captured directly inside
// shared_pretl_read (direct child), so the completion-TC virtual source
// AR no longer exists; source identity is proven by two independent raw
// parents instead of a TC virtual AR count.
if (shared_source) {
    CHECK(top->dbg_shared_parents == 2,
          "natural(shared): expected two independent raw source parents");
} else {
    CHECK((n_nat_var > 0 || (task_physical_bypass>0 && n_nat_par>0)),
          "natural: no virtual source read request was observed");
}
CHECK(n_nat_vaw > 0,
      "natural: no virtual write request was observed");

